package hu.synostream.android;
import android.content.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.UiDevice;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
@RunWith(AndroidJUnit4.class) public class Android0510Test {
 final Android050FlowTest f=new Android050FlowTest();
 @Before public void init(){f.instrumentation=InstrumentationRegistry.getInstrumentation();f.context=f.instrumentation.getTargetContext();f.app=(SynoApp)f.context.getApplicationContext();f.device=UiDevice.getInstance(f.instrumentation);UiLocale.save(f.context,"hu");}
 @After public void cleanup()throws Exception{UiLocale.save(f.context,"hu");f.instrumentation.runOnMainSync(()->{f.app.cancelScan();f.app.epoch++;f.app.torrentDraft.close();f.app.externalTorrentUri=null;f.app.externalTorrentMime=null;});f.cleanup();}
 void write(File file,String value)throws Exception{try(FileOutputStream out=new FileOutputStream(file)){out.write(value.getBytes(StandardCharsets.UTF_8));}}
 void drain()throws Exception{CountDownLatch done=new CountDownLatch(1);f.app.cacheIo.execute(()->f.app.main.post(done::countDown));assertTrue(done.await(10,TimeUnit.SECONDS));}
 @Test public void removalReturnsWithoutCacheLockAndKeepsCapturedIdentityAndLibrary()throws Exception{try(FakeNas nas=new FakeNas()){f.setup(nas,List.of());JSONObject library=f.app.selected();File original=f.app.cacheFile(library);write(original,"[]");java.lang.reflect.Field field=SynoApp.class.getDeclaredField("cacheLock");field.setAccessible(true);Object lock=field.get(f.app);CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1),returned=new CountDownLatch(1);AtomicReference<File> later=new AtomicReference<>();f.app.cacheIo.execute(()->{synchronized(lock){entered.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}}});assertTrue(entered.await(3,TimeUnit.SECONDS));try{f.app.main.post(()->{try{f.app.removeCache(library);f.app.identity="later-fixture-"+System.nanoTime();LibraryConfig.paths(library,List.of("/Other"));File changed=f.app.cacheFile(library);later.set(changed);write(changed,"[]");}catch(Exception e){throw new RuntimeException(e);}finally{returned.countDown();}});assertTrue("removeCache must not wait for the cache lock",returned.await(3,TimeUnit.SECONDS));assertEquals(1,release.getCount());assertTrue(original.exists());assertNotNull(later.get());release.countDown();drain();assertFalse(original.exists());assertTrue(later.get().exists());}finally{release.countDown();}}}
 @Test public void metadataSaveWritesSubmissionSnapshotAfterCardChanges()throws Exception{try(FakeNas nas=new FakeNas()){Library.Card card=new Library.Card("/Movies/Snapshot.mkv","Original",true);card.memberPaths.add(card.path);f.setup(nas,List.of(card));File file=f.app.cacheFile(f.app.selected());CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);f.app.cacheIo.execute(()->{entered.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}});assertTrue(entered.await(3,TimeUnit.SECONDS));try{JSONObject info=new JSONObject().put("id",42).put("title","Saved title").put("overview","Saved overview");f.instrumentation.runOnMainSync(()->{f.app.updatedInfo(card,info);card.title="Later title";card.memberPaths.add("/Movies/Later.mkv");});release.countDown();drain();JSONArray saved=new JSONArray(new String(NasClient.readBounded(new FileInputStream(file),20*1024*1024),StandardCharsets.UTF_8));assertEquals("Saved title",saved.getJSONObject(0).getString("title"));assertEquals(1,saved.getJSONObject(0).getJSONArray("members").length());assertEquals("Later title",card.title);}finally{release.countDown();}}}
 @Test public void loadFinishesWhileNasWorkerRemainsBlocked()throws Exception{try(FakeNas nas=new FakeNas()){f.setup(nas,List.of());JSONObject library=f.app.selected();write(f.app.cacheFile(library),new JSONArray().put(new Library.Card("/Movies/Cached.mkv","Cached fixture",true).json()).toString());CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1),completed=new CountDownLatch(1);f.app.worker.execute(()->{entered.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}});assertTrue(entered.await(3,TimeUnit.SECONDS));try{f.instrumentation.runOnMainSync(()->f.app.loadCache(library,completed::countDown));assertTrue(completed.await(5,TimeUnit.SECONDS));assertEquals(1,release.getCount());assertFalse(f.app.busy);assertEquals("Cached fixture",f.app.cards.get(0).title);}finally{release.countDown();}}}
 @Test public void olderLoadCannotReleaseNewerLoadOrRunItsCallback()throws Exception{try(FakeNas nas=new FakeNas()){f.setup(nas,List.of());JSONObject library=f.app.selected();write(f.app.cacheFile(library),new JSONArray().put(new Library.Card("/Movies/Cached.mkv","Cached fixture",true).json()).toString());CountDownLatch firstEntered=new CountDownLatch(1),releaseFirst=new CountDownLatch(1),middleEntered=new CountDownLatch(1),releaseMiddle=new CountDownLatch(1),completed=new CountDownLatch(1);AtomicInteger oldCalls=new AtomicInteger();f.app.cacheIo.execute(()->{firstEntered.countDown();try{releaseFirst.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}});assertTrue(firstEntered.await(3,TimeUnit.SECONDS));try{f.instrumentation.runOnMainSync(()->{f.app.loadCache(library,oldCalls::incrementAndGet);f.app.cacheIo.execute(()->{middleEntered.countDown();try{releaseMiddle.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}});f.app.loadCache(library,completed::countDown);});releaseFirst.countDown();assertTrue(middleEntered.await(5,TimeUnit.SECONDS));f.instrumentation.waitForIdleSync();assertTrue(f.app.busy);assertEquals(0,oldCalls.get());releaseMiddle.countDown();assertTrue(completed.await(5,TimeUnit.SECONDS));assertFalse(f.app.busy);assertEquals(0,oldCalls.get());assertEquals("Cached fixture",f.app.cards.get(0).title);}finally{releaseFirst.countDown();releaseMiddle.countDown();}}}
}
